    monkeypatch.setattr(ledger.rates, '_DEFAULT_RATES', {'USD': 1.0, 'EUR': 0.9, 'GBP': 0.8, 'JPY': 150.0})
    assert ledger.rates.exchange_rate('') == 1.0

